 async function addIdea(noteId){const note=ideas().find(x=>x.id===noteId);if(!note)throw Error('Saved idea not found.');const trips=db().trips;openModal('Add idea to a trip',`<form id="travel-add-idea" data-note-id="${esc(noteId)}"><label>Trip<select name="tripId">${trips.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}<option value="new">＋ Create a new trip</option></select></label><div class="travel-new-trip-fields" ${trips.length?'hidden':''}><label>New trip name<input name="tripName" maxlength="100" placeholder="A week in Florence"></label><label>Destination<input name="destination"></label></div><div class="modal-footer"><button type="button" class="secondary" data-action="close-modal">Cancel</button><button class="travel-primary" type="submit">Add to trip</button></div></form>`);const select=document.querySelector('#travel-add-idea [name=tripId]'),fields=document.querySelector('.travel-new-trip-fields');select.addEventListener('change',()=>fields.hidden=select.value!=='new');}
 function offlineKey(id){return new Request(location.origin+'/__unbound-travel-offline__/'+encodeURIComponent(id));}
 async function fetchAttachment(a){return a.provider==='google'?google.downloadTravelAttachment(a.fileId):a.provider==='dropbox'?cloud.Dropbox.downloadTravelAttachment(a.path):a.provider==='box'?cloud.Box.downloadTravelAttachment(a.fileId):null;}
 async function upload(file,bookingId,provider){if(!file)throw Error('Choose a document.');if(file.size>25*1024*1024)throw Error('Choose a file smaller than 25 MB.');const extension=String(file.name||'').split('.').pop().toLowerCase(),mime=file.type||({pdf:'application/pdf',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',gif:'image/gif',bmp:'image/bmp',tif:'image/tiff',tiff:'image/tiff'}[extension]||'');if(!mime.startsWith('image/')&&mime!=='application/pdf')throw Error('Choose a PDF or supported image.');const booking=db().bookings.find(x=>x.id===bookingId);if(!booking)throw Error('Booking not found.');let uploaded;if(provider==='google')uploaded=await google.uploadTravelAttachment(file,booking.tripId,booking.id);else if(provider==='dropbox')uploaded=await cloud.Dropbox.uploadTravelAttachment(file,booking.tripId,booking.id);else if(provider==='box')uploaded=await cloud.Box.uploadTravelAttachment(file,booking.tripId,booking.id);else throw Error('Choose a cloud provider.');db().attachments.push({id:uid(),tripId:booking.tripId,bookingId,provider,fileId:uploaded.id||null,path:uploaded.path_lower||null,name:file.name,mimeType:mime,size:file.size,createdAt:new Date().toISOString(),url:provider==='google'?uploaded.webViewLink||'':null});save();closeModal();renderApp();toast('Attachment saved to '+(provider==='google'?'Google Drive':'Dropbox')+'.');}
